package com.lamggm.rospocket;
import android.widget.*;import java.io.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
/** Android integration, explicitly fake metadata transport; no robot commands. */
@RunWith(RobolectricTestRunner.class) @Config(sdk=31) @LooperMode(LooperMode.Mode.PAUSED)
public class KnownRobotProfileActivityTest {
 final ConnectionActivityTest f=new ConnectionActivityTest();
 @Before public void setup()throws Exception{f.setup();}
 @After public void cleanup()throws Exception{f.cleanup();}
 BenchProfiles book()throws Exception{return new ProfileStore(new File(f.a.getFilesDir(),"bench-profiles-v1.json")).load();}
 DashboardBoard board(){return f.a.getWindow().getDecorView().findViewWithTag("dashboard-board");}
 void click(int id){f.a.findViewById(id).performClick();f.paint();}
 RobotContext.Snapshot observe()throws Exception{return ((RobotContext)f.get("robotContext")).observe(new RobotDashboardTest.Fake(),InputRules.domain(((EditText)f.a.findViewById(R.id.domain)).getText().toString()),"192.0.2.2",((EditText)f.a.findViewById(R.id.peer)).getText().toString(),"lan","jazzy",RobotDashboardTest.topics("/test/robot_description"),()->true);}
 void deliver(RobotContext.Snapshot s)throws Exception{f.call("onRobotObserved",new Class<?>[]{RobotContext.Snapshot.class},s);f.paint();}
 void save(String name){click(R.id.profile_new);((EditText)f.a.findViewById(R.id.profile_name)).setText(name);click(R.id.profile_save);}
 void apply(int index){((Spinner)f.a.findViewById(R.id.profile_select)).setSelection(index);f.paint();click(R.id.profile_apply);}
 void pairAndChooseOther()throws Exception{deliver(observe());save("Known robot");assertNotNull(book().profiles.get(0).robot);click(R.id.connect);save("Other panel");apply(2);click(R.id.connect);}
 @Test public void workerRecoveryRequiresANewDescriptionBeforeAssociatingProfile()throws Exception{deliver(observe());((RobotContext)f.get("robotContext")).resetWorker();save("No active observation");assertNull("Description from retired worker cannot associate a profile",book().profiles.get(0).robot);deliver(observe());save("Fresh observation");assertNotNull(book().profiles.get(1).robot);}
 @Test public void adHocEditsWithoutAnAppliedProfileMustSurviveAutomaticRecognition()throws Exception{pairAndChooseOther();click(R.id.profile_delete);org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog().getButton(-1).performClick();f.paint();assertNull(book().applied);f.call("requestExtra",new Class<?>[]{int.class,String.class,String.class,boolean.class,boolean.class},1,"rt/manual","std_msgs::msg::dds_::Float64_",false,false);deliver(observe());assertNull("Unsaved ad hoc setup must not be replaced",book().applied);assertEquals("rt/manual",((WatchSlots)f.get("watchSlots")).get(1).wire);}
 @Test public void reconnectingKnownSameIdLoadsSavedChangesButDoesNotLoop()throws Exception{deliver(observe());save("Known A");click(R.id.connect);apply(1);click(R.id.connect);deliver(observe());((SensorPanel)f.get("sensorPanel")).findViewWithTag("sensor-Câmera").performClick();click(R.id.profile_save);assertEquals("scan",book().applied.visual.mode);assertEquals("camera",book().profiles.get(0).visual.mode);click(R.id.connect);click(R.id.connect);deliver(observe());assertEquals("Saved latest configuration, not just its ID, must load","camera",book().applied.visual.mode);Object requested=f.get("requested");deliver(observe());assertSame(requested,f.get("requested"));assertTrue((Boolean)f.get("connectWanted"));}
 @Test public void oneKnownRobotLoadsSavedProfileAndKeepsTransportAndExistingCatalog()throws Exception{pairAndChooseOther();String domain=((EditText)f.a.findViewById(R.id.domain)).getText().toString(),peer=((EditText)f.a.findViewById(R.id.peer)).getText().toString();assertEquals("Other panel",book().applied.name);deliver(observe());assertEquals("Known robot",book().applied.name);assertTrue((Boolean)f.get("connectWanted"));assertEquals(domain,((EditText)f.a.findViewById(R.id.domain)).getText().toString());assertEquals(peer,((EditText)f.a.findViewById(R.id.peer)).getText().toString());assertEquals(2,book().profiles.size());Object config=f.get("requested");deliver(observe());assertSame("Already loaded profile must not reconnect in a loop",config,f.get("requested"));}
 @Test public void openDraftIsPreservedAndNotAppliedLaterInSameConnection()throws Exception{pairAndChooseOther();board().edit();board().resize("plot",4,4);deliver(observe());assertEquals("Other panel",book().applied.name);assertTrue(board().editing());assertEquals(4,board().layout().get("plot").height);board().cancel();deliver(observe());assertEquals("Other panel",book().applied.name);}
 @Test public void cachedDescriptionAfterDisconnectCannotAssociateOrAutoload()throws Exception{RobotContext.Snapshot old=observe();click(R.id.connect);deliver(old);save("Offline profile");assertNull(book().profiles.get(0).robot);assertNull(book().applied);assertFalse((Boolean)f.get("connectWanted"));}
 @Test public void multipleMatchingProfilesRequireExplicitSelectionAndNeverGuess()throws Exception{deliver(observe());save("Known A");save("Known B");click(R.id.connect);apply(1);click(R.id.connect);Object requested=f.get("requested");deliver(observe());assertSame(requested,f.get("requested"));assertEquals("Known A",book().applied.name);assertEquals(2,book().profiles.size());}
 @Test public void savedRobotAssociationSurvivesDashboardEditsRenameAndRestart()throws Exception{deliver(observe());save("Known A");click(R.id.connect);apply(1);board().edit();board().resize("plot",4,4);assertTrue(board().save());assertNotNull(book().applied.robot);assertNotNull(BenchProfiles.importProfile(BenchProfiles.exportProfile(book().applied)).robot);f.call("onStop",new Class<?>[]{});f.a=Robolectric.buildActivity(MainActivity.class).create().get();assertNotNull(((ProfilePanel)f.get("profiles")).applied().robot);assertFalse((Boolean)f.get("connectWanted"));}
}
